mapper.select:


    NOT EXISTS (SELECT 1 FROM mes_tech_doc n WHERE n.prev_id = d.id)
    AND d.doc_type = #{docType}
    AND d.status = #{status}
    AND d.material_id = #{materialId}

        AND (d.doc_no LIKE CONCAT('%', #{keyword}, '%') OR d.name LIKE CONCAT('%', #{keyword}, '%')
             OR m.code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY d.id DESC


WHERE d.status = 'RELEASED'
  AND d.material_id IN #{id}
ORDER BY d.material_id, d.doc_type, d.doc_no
